            ss = _mm256_castps128_ps256(_mm_set1_ps(offset));
            MM256_SUM(0, 0);
            MM256_LOAD(1, x+1);
            MM256_SUM(1, 1);
            ssi0 = MM256_OUT(x);

            ss = _mm256_castps128_ps256(_mm_set1_ps(offset));
            MM256_SUM(1, 0);
            MM256_LOAD(2, x+3);
            MM256_SUM(2, 1);
