/* 8 bits for result. Table can overflow [0, 1.0] range,
   so we need extra bits for overflow and negative values.
   NOTE: This value should be the same as in _imaging/_prepare_lut_table() */
#define PRECISION_BITS (16 - 8 - 2)
#define PRECISION_ROUNDING (1 << (PRECISION_BITS - 1))

/* 8 - scales are multiplied on byte.
   6 - max index in the table
       (max size is 65, but index 64 is not reachable) */
#define SCALE_BITS (32 - 8 - 6)
#define SCALE_MASK ((1 << SCALE_BITS) - 1)

#define SHIFT_BITS (16 - 1)

#if defined(_OPENMP)
#include <omp.h>
#endif

#if defined(__SSE4_2__)
#include <emmintrin.h>
#include <smmintrin.h>
#endif

#if defined(__AVX2__)
#include <immintrin.h>
#endif

static inline UINT8
clip8(int in) {
    return clip8_lookups[(in + PRECISION_ROUNDING) >> PRECISION_BITS];
}

#if defined(__SSE4_2__)
/* SSE4.2 optimized interpolate3: compute all 3 channels in parallel */
static inline void
interpolate3_sse(INT16 out[3], const INT16 a[3], const INT16 b[3], INT16 shift) {
    __m128i va = _mm_loadl_epi64((__m128i*)a);  /* 4 x INT16, upper 2 zero */
    __m128i vb = _mm_loadl_epi64((__m128i*)b);
    __m128i vshift = _mm_set1_epi16(shift);
    __m128i vmax_minus_shift = _mm_set1_epi16((1 << SHIFT_BITS) - shift);

    __m128i result = _mm_add_epi16(
        _mm_mullo_epi16(va, vmax_minus_shift),
        _mm_mullo_epi16(vb, vshift)
    );
    result = _mm_srai_epi16(result, SHIFT_BITS);
    _mm_storel_epi64((__m128i*)out, result);
}

static inline void
interpolate4_sse(INT16 out[4], const INT16 a[4], const INT16 b[4], INT16 shift) {
    __m128i va = _mm_loadu_si128((__m128i*)a);
    __m128i vb = _mm_loadu_si128((__m128i*)b);
    __m128i vshift = _mm_set1_epi16(shift);
    __m128i vmax_minus_shift = _mm_set1_epi16((1 << SHIFT_BITS) - shift);

    __m128i result = _mm_add_epi16(
        _mm_mullo_epi16(va, vmax_minus_shift),
        _mm_mullo_epi16(vb, vshift)
    );
    result = _mm_srai_epi16(result, SHIFT_BITS);
    _mm_storeu_si128((__m128i*)out, result);
}

#define interpolate3 interpolate3_sse
#define interpolate4 interpolate4_sse

#else

static inline void
interpolate3(INT16 out[3], const INT16 a[3], const INT16 b[3], INT16 shift) {
    out[0] = (a[0] * ((1 << SHIFT_BITS) - shift) + b[0] * shift) >> SHIFT_BITS;
    out[1] = (a[1] * ((1 << SHIFT_BITS) - shift) + b[1] * shift) >> SHIFT_BITS;
    out[2] = (a[2] * ((1 << SHIFT_BITS) - shift) + b[2] * shift) >> SHIFT_BITS;
}

static inline void
interpolate4(INT16 out[4], const INT16 a[4], const INT16 b[4], INT16 shift) {
