        idx_table1D[i] = (idx1D >> SCALE_BITS);
        shift_table1D[i] = (SCALE_MASK & idx1D) >> (SCALE_BITS - SHIFT_BITS);

        UINT32 idx2D = i * scale2D;
        idx_table2D[i] = (idx2D >> SCALE_BITS);
        shift_table2D[i] = (SCALE_MASK & idx2D) >> (SCALE_BITS - SHIFT_BITS);

        UINT32 idx3D = i * scale3D;
        idx_table3D[i] = (idx3D >> SCALE_BITS);
        shift_table3D[i] = (SCALE_MASK & idx3D) >> (SCALE_BITS - SHIFT_BITS);
    }

    ImagingSectionEnter(&cookie);

    if (table_channels == 3) {
        int stride2D_ch = size1D * 3;
        int stride3D_ch = size1D_2D * 3;

        #pragma omp parallel for private(x) schedule(static)
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 * restrict rowIn = (UINT8 *)imIn->image[y];
            UINT32 * restrict rowOut = (UINT32 *)imOut->image[y];

            for (x = 0; x < imOut->xsize; x++) {
                int off = x * 4;
                UINT8 r = rowIn[off + 0];
                UINT8 g = rowIn[off + 1];
                UINT8 b = rowIn[off + 2];
                UINT8 a = rowIn[off + 3];

                int idx = (idx_table1D[r] + idx_table2D[g] * size1D + idx_table3D[b] * size1D_2D) * 3;
                INT16 sh1 = shift_table1D[r];
                INT16 sh2 = shift_table2D[g];
                INT16 sh3 = shift_table3D[b];

                INT16 left[3], right[3];
                INT16 leftleft[3], leftright[3], rightleft[3], rightright[3];

                interpolate3(leftleft, &table[idx + 0], &table[idx + 3], sh1);
                interpolate3(
                    leftright,
                    &table[idx + stride2D_ch],
                    &table[idx + stride2D_ch + 3],
                    sh1);
                interpolate3(left, leftleft, leftright, sh2);

                interpolate3(
                    rightleft,
                    &table[idx + stride3D_ch],
                    &table[idx + stride3D_ch + 3],
                    sh1);
                interpolate3(
                    rightright,
                    &table[idx + stride3D_ch + stride2D_ch],
                    &table[idx + stride3D_ch + stride2D_ch + 3],
                    sh1);
                interpolate3(right, rightleft, rightright, sh2);

                interpolate3(left /* reuse as result */, left, right, sh3);

