                    clip8(left[0]),
                    clip8(left[1]),
                    clip8(left[2]),
                    a);
            }
        }
    } else { /* table_channels == 4 */
        int stride2D_ch = size1D * 4;
        int stride3D_ch = size1D_2D * 4;

        #pragma omp parallel for private(x) schedule(static)
        for (y = 0; y < imOut->ysize; y++) {
            UINT8 * restrict rowIn = (UINT8 *)imIn->image[y];
            UINT32 * restrict rowOut = (UINT32 *)imOut->image[y];

            for (x = 0; x < imOut->xsize; x++) {
                int off = x * 4;
                UINT8 r = rowIn[off + 0];
                UINT8 g = rowIn[off + 1];
                UINT8 b = rowIn[off + 2];

                int idx = (idx_table1D[r] + idx_table2D[g] * size1D + idx_table3D[b] * size1D_2D) * 4;
                INT16 sh1 = shift_table1D[r];
                INT16 sh2 = shift_table2D[g];
                INT16 sh3 = shift_table3D[b];

                INT16 left[4], right[4];
                INT16 leftleft[4], leftright[4], rightleft[4], rightright[4];

                interpolate4(leftleft, &table[idx + 0], &table[idx + 4], sh1);
                interpolate4(
                    leftright,
                    &table[idx + stride2D_ch],
                    &table[idx + stride2D_ch + 4],
                    sh1);
                interpolate4(left, leftleft, leftright, sh2);

                interpolate4(
                    rightleft,
                    &table[idx + stride3D_ch],
                    &table[idx + stride3D_ch + 4],
                    sh1);
                interpolate4(
                    rightright,
                    &table[idx + stride3D_ch + stride2D_ch],
                    &table[idx + stride3D_ch + stride2D_ch + 4],
                    sh1);
                interpolate4(right, rightleft, rightright, sh2);

                interpolate4(left /* reuse as result */, left, right, sh3);

                rowOut[x] = MAKE_UINT32(
                    clip8(left[0]),
                    clip8(left[1]),
                    clip8(left[2]),
                    clip8(left[3]));
            }
        }
    }

    ImagingSectionLeave(&cookie);

    return imOut;
}
